-- Local Auth/Storage metadata fixtures, not real bank transactions or HTTP.
begin;
create function pg_temp.assert_true(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end;$$;
create function pg_temp.expect_error(q text,code text) returns void language plpgsql as $$declare actual text;begin begin execute q;exception when others then get stacked diagnostics actual=returned_sqlstate;if actual<>code then raise exception 'FAIL expected %, got %: %',code,actual,q;end if;return;end;raise exception 'FAIL expected rejection: %',q;end;$$;
insert into auth.users(id) values('c1000000-0000-4000-8000-000000000001'),('c1000000-0000-4000-8000-000000000002');
create function pg_temp.pay(n integer) returns uuid language sql as $$select ('c2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.receipt(n integer) returns uuid language sql as $$select ('c3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.path(n integer) returns text language sql as $$select 'c1000000-0000-4000-8000-000000000001/receipts/c4000000-0000-4000-8000-000000000001/'||pg_temp.pay(n)::text||'/'||pg_temp.receipt(n)::text||'.pdf'$$;
create function pg_temp.cash(n integer,amount text) returns uuid language sql as $$select public.report_request_payment(pg_temp.pay(n),'c4000000-0000-4000-8000-000000000001','c5000000-0000-4000-8000-000000000001','cash',amount,current_date,'')$$;
create function pg_temp.bank(n integer,amount text,bank_version integer default 1) returns uuid language sql as $$select public.report_request_payment(pg_temp.pay(n),'c4000000-0000-4000-8000-000000000001','c5000000-0000-4000-8000-000000000001','bank_transfer',amount,current_date,'TX-123',pg_temp.receipt(n),bank_version)$$;
create function pg_temp.state() returns jsonb language sql as $$select public.request_payment_state('c4000000-0000-4000-8000-000000000001')$$;
create function pg_temp.fail_payment_alert() returns trigger language plpgsql as $$begin if new.kind like 'payment_%' and current_setting('test.fail_payment',true)='yes' then raise exception 'Injected payment alert failure' using errcode='23514';end if;return new;end;$$;
create trigger fail_payment_alert before insert on public.request_notifications for each row execute function pg_temp.fail_payment_alert();
select pg_temp.assert_true((select not public and file_size_limit=5242880 and 'application/pdf'=any(allowed_mime_types) from storage.buckets where id='request-payment-receipts'),'separate private receipt bucket and PDF/image size limits');
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select public.initialize_tailor_profile();
select public.save_tailor_profile('{"shop_name":"Payment Atelier","description":"Bespoke garments for special occasions.","specialties":"Dresses","city":"Colombo","public_address":"123 Public Street","business_phone":"+94112223344","years_experience":5,"accepting_requests":true}',true,1);
select public.save_tailor_bank('{"account_holder":"Tailor Holder","bank":"Bank A","branch":"Colombo","account_number":"00001234"}',null);
select public.save_tailor_bank('{"account_holder":"Tailor Holder","bank":"Bank A","branch":"Colombo","account_number":"00001234"}',null);
select pg_temp.assert_true((select account_number='00001234' and version=1 from public.tailor_bank_accounts),'bank account numbers retain leading zeros and saves retry exactly');
select pg_temp.expect_error($q$select public.save_tailor_bank('{"account_holder":"X","bank":"Y","branch":"Z","account_number":"0000","pin":"1234"}',1)$q$,'22023');
select pg_temp.expect_error($q$select public.save_tailor_bank(jsonb_build_object('account_holder',chr(160),'bank','Y','branch','Z','account_number','0000'),1)$q$,'22023');
select set_config('request.jwt.claim.sub','c1000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true((select count(*)=0 from public.tailor_bank_accounts),'no bank details before eligible request');
select pg_temp.expect_error($q$select public.save_tailor_bank('{}',null)$q$,'42501');
select public.send_tailoring_request('c4000000-0000-4000-8000-000000000001','50000000-0000-4000-8000-000000000002','dress','Direct payment discussion.',1,current_date+30);
select public.send_tailoring_request('c4000000-0000-4000-8000-000000000002','50000000-0000-4000-8000-000000000002','dress','No accepted quotation yet.',1,current_date+30);
select pg_temp.assert_true((public.request_payment_state('c4000000-0000-4000-8000-000000000002')->>'eligible')='false','legacy request without payment agreement has no fabricated amount');
select pg_temp.expect_error($q$select public.report_request_payment(pg_temp.pay(1),'c4000000-0000-4000-8000-000000000002','c5000000-0000-4000-8000-000000000001','cash','1.00',current_date,'')$q$,'22023');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select public.decide_tailoring_request('c4000000-0000-4000-8000-000000000001','accepted','',1);
select public.send_request_quotation('c5000000-0000-4000-8000-000000000001','c4000000-0000-4000-8000-000000000001',2,'100.10','20.20','0.00','','Agreed payment basis');
select pg_temp.expect_error($q$select public.reserve_payment_receipt(pg_temp.receipt(6),'c4000000-0000-4000-8000-000000000001',pg_temp.pay(6),'pdf')$q$,'42501');
select set_config('request.jwt.claim.sub','c1000000-0000-4000-8000-000000000001',true);
select pg_temp.expect_error('select pg_temp.cash(1,''1.00'')','22023');
select public.answer_request_quotation('c5000000-0000-4000-8000-000000000001','accepted',1);
select pg_temp.assert_true((select count(*)=1 and bool_and(account_number='00001234') from public.tailor_bank_accounts),'eligible customer can view destination privately');
select pg_temp.assert_true(pg_temp.state()->>'total'='120.30' and pg_temp.state()->>'balance'='120.30','immutable quotation total uses exact decimals');
do $$declare value text;begin foreach value in array array['0','-1','NaN','Infinity','1e2','0.001','9999999999999.00','121.00'] loop perform pg_temp.expect_error(format('select pg_temp.cash(1,%L)',value),'22023');end loop;end;$$;
select pg_temp.expect_error($q$select public.report_request_payment(pg_temp.pay(1),'c4000000-0000-4000-8000-000000000001','c5000000-0000-4000-8000-000000000001','cash','1.00',(clock_timestamp() at time zone 'Asia/Colombo')::date+1,'')$q$,'22023');
select pg_temp.cash(1,'20.10');select pg_temp.cash(1,'20.10');select pg_temp.cash(2,'30.20');
select pg_temp.assert_true(pg_temp.state()->>'confirmed'='0.00' and pg_temp.state()->>'awaiting'='50.30' and pg_temp.state()->>'balance'='120.30','pending advance and balance reports never count as paid');
select pg_temp.expect_error('select pg_temp.cash(1,''21.00'')','22023');
select pg_temp.expect_error($q$select public.decide_request_payment(pg_temp.pay(1),'confirmed','',1,true)$q$,'42501');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select pg_temp.expect_error($q$select public.decide_request_payment(pg_temp.pay(1),'confirmed','',1,false)$q$,'22023');
select pg_temp.expect_error($q$select public.decide_request_payment(pg_temp.pay(1),'confirmed','',2,true)$q$,'40001');
select set_config('test.fail_payment','yes',true);select pg_temp.expect_error($q$select public.decide_request_payment(pg_temp.pay(1),'confirmed','',1,true)$q$,'23514');
select pg_temp.assert_true(pg_temp.state()->>'confirmed'='0.00','failed confirmation notification rolls back confirmation and totals');
select set_config('test.fail_payment','no',true);
select public.decide_request_payment(pg_temp.pay(1),'confirmed','',1,true);select public.decide_request_payment(pg_temp.pay(1),'confirmed','',1,true);
select pg_temp.assert_true(pg_temp.state()->>'confirmed'='20.10' and pg_temp.state()->>'balance'='100.20','confirmed advance reduces exact balance once');
select pg_temp.expect_error($q$select public.decide_request_payment(pg_temp.pay(2),'rejected',' ',1,false)$q$,'22023');
select public.decide_request_payment(pg_temp.pay(2),'rejected','Not received',1,false);
select public.decide_request_payment(pg_temp.pay(2),'rejected','Not received',1,false);
select pg_temp.assert_true(pg_temp.state()->>'awaiting'='0.00' and pg_temp.state()->>'balance'='100.20','rejected reports never count as received');
select pg_temp.expect_error($q$select public.decide_request_payment(pg_temp.pay(1),'rejected','Changed my mind',1,false)$q$,'40001');
select set_config('request.jwt.claim.sub','c1000000-0000-4000-8000-000000000001',true);
select pg_temp.cash(3,'30.20');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select public.decide_request_payment(pg_temp.pay(3),'confirmed','',1,true);
select pg_temp.assert_true(pg_temp.state()->>'confirmed'='50.30' and pg_temp.state()->>'balance'='70.00','corrected new submission preserves rejected report');
select set_config('request.jwt.claim.sub','c1000000-0000-4000-8000-000000000001',true);
select pg_temp.cash(4,'50.00');select pg_temp.cash(5,'50.00');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
savepoint reverse_confirmation_order;
select public.decide_request_payment(pg_temp.pay(5),'confirmed','',1,true);
select pg_temp.expect_error($q$select public.decide_request_payment(pg_temp.pay(4),'confirmed','',1,true)$q$,'22023');
select pg_temp.assert_true(pg_temp.state()->>'balance'='20.00','either competing confirmation winner leaves exact remaining balance');
rollback to savepoint reverse_confirmation_order;release savepoint reverse_confirmation_order;
select public.decide_request_payment(pg_temp.pay(4),'confirmed','',1,true);
select pg_temp.expect_error($q$select public.decide_request_payment(pg_temp.pay(5),'confirmed','',1,true)$q$,'22023');
select pg_temp.assert_true(pg_temp.state()->>'confirmed'='100.30' and pg_temp.state()->>'balance'='20.00','competing confirmation cannot exceed agreed total');
select public.decide_request_payment(pg_temp.pay(5),'rejected','Duplicate report',1,false);
select set_config('request.jwt.claim.sub','c1000000-0000-4000-8000-000000000001',true);
select public.reserve_payment_receipt(pg_temp.receipt(6),'c4000000-0000-4000-8000-000000000001',pg_temp.pay(6),'pdf');
select public.reserve_payment_receipt(pg_temp.receipt(6),'c4000000-0000-4000-8000-000000000001',pg_temp.pay(6),'pdf');
select pg_temp.expect_error($q$select public.reserve_payment_receipt(pg_temp.receipt(8),'c4000000-0000-4000-8000-000000000001',pg_temp.pay(6),'pdf')$q$,'22023');
select pg_temp.expect_error('select pg_temp.bank(6,''20.00'')','22023');
savepoint receipt_probe;
insert into storage.objects(bucket_id,name,metadata) values('request-payment-receipts',pg_temp.path(6),'{"contentLength":100,"mimetype":"application/pdf"}');
select pg_temp.assert_true(not public.payment_receipt_ready(pg_temp.receipt(6)),'probe metadata does not qualify as completed receipt');
select pg_temp.expect_error('select pg_temp.bank(6,''20.00'')','22023');
rollback to savepoint receipt_probe;release savepoint receipt_probe;
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-payment-receipts',pg_temp.path(6),'{"size":5242881,"mimetype":"application/pdf"}')$q$,'42501');
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-payment-receipts',pg_temp.path(6),'{"size":100,"mimetype":"text/html"}')$q$,'42501');
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-payment-receipts',pg_temp.path(6),'{"size":0,"mimetype":"application/pdf"}')$q$,'42501');
insert into storage.objects(bucket_id,name,metadata) values('request-payment-receipts',pg_temp.path(6),'{"size":5242880,"mimetype":"application/pdf"}');
select pg_temp.expect_error($q$select public.report_request_payment(pg_temp.pay(8),'c4000000-0000-4000-8000-000000000001','c5000000-0000-4000-8000-000000000001','bank_transfer','20.00',current_date,'TX',pg_temp.receipt(6),1)$q$,'42501');
select set_config('test.fail_payment','yes',true);select pg_temp.expect_error('select pg_temp.bank(6,''20.00'')','23514');
select pg_temp.assert_true((select payment_id is null from public.payment_receipt_uploads where id=pg_temp.receipt(6)),'submission failure rolls back receipt attachment');
select set_config('test.fail_payment','no',true);select pg_temp.bank(6,'20.00');select pg_temp.bank(6,'20.00');
select pg_temp.assert_true(pg_temp.state()->>'confirmed'='100.30' and pg_temp.state()->>'awaiting'='20.00','receipt alone does not count money as received');
delete from storage.objects where bucket_id='request-payment-receipts' and name=pg_temp.path(6);
select pg_temp.assert_true((select count(*)=1 from storage.objects where bucket_id='request-payment-receipts'),'pending submitted receipt is already protected');
select pg_temp.assert_true((select destination->>'account_number'='00001234' from public.request_payments where id=pg_temp.pay(6)),'reviewed destination frozen with leading zeros');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
select public.save_tailor_bank('{"account_holder":"Tailor Holder","bank":"Bank B","branch":"Kandy","account_number":"00009999"}',1);
select pg_temp.assert_true((select destination->>'bank'='Bank A' from public.request_payments where id=pg_temp.pay(6)),'bank account edit does not rewrite history');
select set_config('request.jwt.claim.sub','c1000000-0000-4000-8000-000000000001',true);
select public.reserve_payment_receipt(pg_temp.receipt(8),'c4000000-0000-4000-8000-000000000001',pg_temp.pay(8),'pdf');
insert into storage.objects(bucket_id,name,metadata) values('request-payment-receipts',pg_temp.path(8),'{"size":100,"mimetype":"application/pdf"}');
select pg_temp.expect_error('select pg_temp.bank(8,''20.00'',1)','40001');
select pg_temp.assert_true((select count(*)=0 from public.request_payments where id=pg_temp.pay(8)),'stale reviewed bank version cannot submit a different destination');
delete from storage.objects where bucket_id='request-payment-receipts' and name=pg_temp.path(8);select public.release_payment_receipt(pg_temp.receipt(8));
savepoint independent_completion;
reset role;update public.tailoring_requests set completed_at=now() where id='c4000000-0000-4000-8000-000000000001';set local role authenticated;
select pg_temp.assert_true(pg_temp.state()->>'awaiting'='20.00' and pg_temp.state()->>'eligible'='true','completion is independent of pending payments; eligible history remains');
rollback to savepoint independent_completion;release savepoint independent_completion;
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000002',true);
savepoint rejected_receipt_history;
select public.decide_request_payment(pg_temp.pay(6),'rejected','Incorrect reference',1,false);
select set_config('request.jwt.claim.sub','c1000000-0000-4000-8000-000000000001',true);
delete from storage.objects where bucket_id='request-payment-receipts';
select pg_temp.assert_true((select count(*)=1 from storage.objects where bucket_id='request-payment-receipts'),'rejected receipt remains immutable and private');
select pg_temp.assert_true(pg_temp.state()->>'balance'='20.00' and pg_temp.state()->>'awaiting'='0.00','rejected receipt never counts as money received');
rollback to savepoint rejected_receipt_history;release savepoint rejected_receipt_history;
select pg_temp.assert_true((select count(*)=1 from storage.objects where bucket_id='request-payment-receipts'),'addressed tailor sees submitted receipt');
do $$declare old_row jsonb;begin select to_jsonb(r) into old_row from public.tailoring_requests r where id='c4000000-0000-4000-8000-000000000001';perform public.decide_request_payment(pg_temp.pay(6),'confirmed','',1,true);perform pg_temp.assert_true((old_row-'payment_revision')=(select to_jsonb(r)-'payment_revision' from public.tailoring_requests r where id='c4000000-0000-4000-8000-000000000001'),'payment confirmation does not change design, deadline, quote or work stage/version');end;$$;
select pg_temp.assert_true(pg_temp.state()->>'confirmed'='120.30' and pg_temp.state()->>'balance'='0.00','partial payments sum exactly to agreed total');
select pg_temp.assert_true((select count(*)=6 from public.request_notifications where kind='payment_reported'),'report notifications are deduplicated');
select set_config('request.jwt.claim.sub','c1000000-0000-4000-8000-000000000001',true);
select pg_temp.bank(6,'20.00');
select pg_temp.expect_error('select pg_temp.cash(7,''0.01'')','22023');
update storage.objects set metadata='{"size":10,"mimetype":"application/pdf"}' where bucket_id='request-payment-receipts';
delete from storage.objects where bucket_id='request-payment-receipts';
select pg_temp.assert_true((select metadata->>'size'='5242880' from storage.objects where bucket_id='request-payment-receipts'),'attached receipt cannot be overwritten or deleted');
select pg_temp.expect_error('update public.request_payments set amount=1','42501');
select pg_temp.expect_error('delete from public.request_payment_decisions','42501');
select pg_temp.expect_error('select public.release_payment_receipt(pg_temp.receipt(6))','22023');
select public.reserve_payment_receipt(pg_temp.receipt(7),'c4000000-0000-4000-8000-000000000001',pg_temp.pay(7),'pdf');
insert into storage.objects(bucket_id,name,metadata) values('request-payment-receipts',pg_temp.path(7),'{"size":100,"mimetype":"application/pdf"}');
reset role;update public.payment_receipt_uploads set created_at=now()-interval '2 hours';set local role authenticated;
select pg_temp.assert_true((select count(*)=1 from public.unused_payment_receipts()),'cleanup excludes submitted receipts and lists caller unused');
select pg_temp.assert_true((select count(*)=0 from public.unused_payment_receipts(pg_temp.pay(7))),'cleanup excludes active draft');
delete from storage.objects where bucket_id='request-payment-receipts' and name=pg_temp.path(7);select public.release_payment_receipt(pg_temp.receipt(7));
select pg_temp.assert_true((select count(*)=6 from public.request_notifications where kind in('payment_confirmed','payment_rejected')),'decision notifications deduplicated');
select set_config('request.jwt.claim.sub','c1000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true((select count(*)=0 from public.request_payments),'stranger cannot read payments');
select pg_temp.assert_true((select count(*)=0 from public.tailor_bank_accounts),'stranger cannot read bank account');
select pg_temp.assert_true((select count(*)=0 from storage.objects where bucket_id='request-payment-receipts'),'stranger cannot sign/list/download receipts');
select pg_temp.expect_error('select pg_temp.state()','42501');select pg_temp.expect_error('select pg_temp.cash(8,''1.00'')','42501');
select set_config('request.jwt.claim.sub','50000000-0000-4000-8000-000000000003',true);
select pg_temp.assert_true((select count(*)=0 from public.tailor_bank_accounts),'unrelated admin cannot read bank details');
select pg_temp.assert_true((select count(*)=0 from public.request_payments),'unrelated admin cannot read payment records');
reset role;
create policy test_broad_receipt_access on storage.objects for all to authenticated using(true) with check(true);
set local role authenticated;
select pg_temp.assert_true((select count(*)=0 from storage.objects where bucket_id='request-payment-receipts'),'restrictive receipt guards block older broad policies');
select pg_temp.expect_error($q$insert into storage.objects(bucket_id,name,metadata) values('request-payment-receipts',pg_temp.path(9),'{"size":100,"mimetype":"application/pdf"}')$q$,'42501');
reset role;set local role anon;
select pg_temp.expect_error('select * from public.payment_details','42501');
select pg_temp.assert_true((select count(*)=0 from storage.objects where bucket_id='request-payment-receipts'),'anonymous receipt access denied');
reset role;rollback;
select 'PASS: direct payments, private banks/receipts, exact partial totals, serialized confirmation bounds, immutable destinations/history, rollback and retry' as result;
